.deal-hero-grid { position:relative; z-index:1; display:grid; grid-template-columns:minmax(0,1.1fr) minmax(320px,.82fr); gap:34px; align-items:center; padding:88px 0; }
.trust-row { display:flex; flex-wrap:wrap; gap:10px; margin:18px 0 0; }
.trust-row span { border:1px solid rgba(244,201,93,.34); background:rgba(244,201,93,.08); color:#fff; border-radius:999px; padding:9px 12px; font-weight:850; font-size:.9rem; }
.deal-card,.pro-card,.booking-card,.fact-card,.package-card,.compare-card { background:linear-gradient(145deg,rgba(255,255,255,.095),rgba(255,255,255,.045)); border:1px solid rgba(255,255,255,.14); border-radius:24px; padding:24px; box-shadow:0 18px 60px rgba(0,0,0,.22); }
.deal-card strong,.gold { color:var(--gold); }
.deal-card .price { font-size:2.2rem; font-weight:950; color:#fff; margin:.2rem 0; }
.deal-card ul,.pro-card ul { margin:16px 0 0; }
.deal-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:16px; }
.two-col-content { display:grid; grid-template-columns:minmax(0,1.05fr) minmax(300px,.95fr); gap:28px; align-items:start; }
.mini-grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(220px,1fr)); gap:16px; }
.jump-list { display:flex; flex-wrap:wrap; gap:10px; margin-top:18px; }
.jump-list a { color:#fff; text-decoration:none; border:1px solid rgba(255,255,255,.14); border-radius:999px; padding:9px 13px; background:rgba(255,255,255,.05); font-size:.92rem; font-weight:850; }
.jump-list a:hover { color:var(--gold); border-color:rgba(244,201,93,.45); }
.package-table { width:100%; border-collapse:collapse; margin:20px 0; overflow:hidden; border-radius:18px; }
.package-table th,.package-table td { padding:14px 16px; text-align:left; border-bottom:1px solid rgba(255,255,255,.10); vertical-align:top; }
.package-table th { background:rgba(244,201,93,.10); color:var(--gold); font-weight:950; }
.package-table tr:hover td { background:rgba(255,255,255,.03); }
.step-list { counter-reset:steps; display:grid; gap:14px; }
.step-list li { list-style:none; counter-increment:steps; position:relative; padding:18px 18px 18px 62px; border:1px solid rgba(42,217,255,.20); background:rgba(42,217,255,.06); border-radius:18px; color:#e8e1ed; }
.step-list li:before { content:counter(steps); position:absolute; left:18px; top:18px; width:30px; height:30px; border-radius:999px; display:grid; place-items:center; background:var(--gold); color:#09090c; font-weight:950; }
.facts-list { display:grid; grid-template-columns:repeat(auto-fit,minmax(230px,1fr)); gap:14px; }
.facts-list div { background:rgba(255,255,255,.045); border:1px solid rgba(255,255,255,.11); border-radius:18px; padding:16px; }
.facts-list dt { color:var(--gold); font-weight:950; margin-bottom:6px; }
.facts-list dd { margin:0; color:#fff; }
.faq-list { display:grid; gap:10px; }
.faq-item { background:rgba(255,255,255,.045); border:1px solid rgba(255,255,255,.12); border-radius:16px; padding:14px 16px; }
.faq-item summary { cursor:pointer; font-weight:950; color:#fff; }
.faq-item p { margin-bottom:0; color:var(--muted); }
.lead-note { color:var(--muted); font-size:.92rem; margin-top:10px; }
.fine-print { font-size:.88rem; color:var(--muted); }
.hero-logo { max-height:88px; object-fit:contain; margin-bottom:12px; }
@media (max-width:1080px) { .deal-hero-grid,.two-col-content { grid-template-columns:1fr; } .deal-grid { grid-template-columns:repeat(2,1fr); } }
@media (max-width:700px) { .deal-hero { min-height:auto; } .deal-hero-grid { padding:56px 0; } .deal-grid { grid-template-columns:1fr; } }

